=<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LinkedIn Automation | AI News Studio</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Orbitron:wght@500;700;900&display=swap" rel="stylesheet">
<style>
:root{--bg:#070b16;--panel:rgba(20,29,48,.72);--border:rgba(120,140,190,.18);--text:#edf2fa;--muted:#94a3b8;--accent:#8b5cf6;--accent2:#38bdf8;--green:#22c55e;--red:#ef4444;--amber:#f59e0b;--ease:cubic-bezier(.22,1,.36,1);--spring:cubic-bezier(.34,1.56,.64,1)}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:"Plus Jakarta Sans",Inter,Arial,sans-serif;background:var(--bg);color:var(--text);min-height:100vh;overflow-x:hidden}
button,input,textarea{font:inherit}button{cursor:pointer}
.aurora{position:fixed;inset:0;z-index:-1;overflow:hidden}
.aurora i{position:absolute;width:46vw;height:46vw;border-radius:50%;filter:blur(110px);opacity:.28;animation:float 18s ease-in-out infinite alternate}
.aurora i:nth-child(1){background:#6d28d9;top:-12vw;left:8vw}
.aurora i:nth-child(2){background:#0ea5e9;bottom:-18vw;right:-6vw;animation-delay:-6s}
.aurora i:nth-child(3){background:#db2777;top:30vh;left:45vw;width:26vw;height:26vw;opacity:.14;animation-delay:-11s}
@keyframes float{to{transform:translate(6vw,4vh) scale(1.15)}}
.app{display:flex;min-height:100vh}
.sidebar{width:250px;background:rgba(9,14,27,.8);backdrop-filter:blur(18px);border-right:1px solid var(--border);padding:24px 14px;position:fixed;inset:0 auto 0 0;overflow-y:auto;z-index:5}
.logo{display:flex;align-items:center;gap:11px;padding:0 10px 26px}
.logo-icon{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#8b5cf6,#38bdf8);display:grid;place-items:center;font-size:20px;box-shadow:0 0 24px #8b5cf666;animation:pulse 3s ease-in-out infinite}
@keyframes pulse{50%{box-shadow:0 0 36px #38bdf877}}
.logo h2{font-size:20px;letter-spacing:-.5px}.logo span{color:#a78bfa}
.nav-label{color:#64748b;font-size:11px;font-weight:700;letter-spacing:1.2px;padding:14px 12px 8px}
.nav-btn{position:relative;display:flex;width:100%;gap:12px;align-items:center;border:0;color:#9caec5;background:transparent;padding:11px 12px;border-radius:10px;text-align:left;margin-bottom:4px;font-size:14px;transition:.25s var(--ease)}
.nav-btn:hover{color:#fff;background:#ffffff0d;transform:translateX(3px)}
.nav-btn.active{color:#fff;background:linear-gradient(90deg,#8b5cf633,transparent)}
.nav-btn.active::before{content:"";position:absolute;left:0;top:20%;bottom:20%;width:3px;border-radius:3px;background:var(--accent);box-shadow:0 0 12px var(--accent)}
.nav-btn b{margin-left:auto;background:var(--accent);color:#fff;font-size:11px;border-radius:20px;padding:2px 8px;display:none}
.nav-btn b.on{display:inline-block;animation:pop .4s var(--spring)}
.sidebar-footer{margin-top:28px;padding:14px;border:1px solid var(--border);border-radius:12px;color:var(--muted);font-size:12px;line-height:1.6}
.main{margin-left:250px;width:calc(100% - 250px);padding:30px}
.topbar{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:28px}
.topbar h1{font-size:26px;letter-spacing:-.6px}.topbar p{color:var(--muted);font-size:13px;margin-top:6px}
.top-actions{display:flex;align-items:center;gap:12px}
.status-pill{background:#0f2a23;color:#4ade80;border:1px solid #1d5943;border-radius:30px;padding:8px 13px;font-size:12px;display:flex;align-items:center;gap:7px}
.status-pill::before{content:"";width:7px;height:7px;border-radius:50%;background:#4ade80;animation:blink 1.6s infinite}
@keyframes blink{50%{opacity:.25;transform:scale(.7)}}
.avatar{width:38px;height:38px;background:linear-gradient(135deg,#4c1d95,#6d5dfc);border-radius:50%;display:grid;place-items:center;font-weight:700}
.page{display:none}.page.active{display:block;animation:pageIn .55s var(--ease)}
@keyframes pageIn{from{opacity:0;transform:translateY(14px);filter:blur(6px)}}
.sh{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:6px 0 16px}
.sh h2{font-size:18px}.sh p{color:var(--muted);font-size:13px;margin-top:5px}
.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:26px}
.card{position:relative;background:var(--panel);backdrop-filter:blur(14px);border:1px solid var(--border);border-radius:16px;transition:transform .35s var(--ease),border-color .3s}
.card::after{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0;transition:opacity .3s;background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),#8b5cf633,transparent 70%)}
.card:hover{transform:translateY(-4px);border-color:#8b5cf666}.card:hover::after{opacity:1}
.stat{padding:20px;animation:rise .6s var(--ease) both;animation-delay:calc(var(--i,0)*70ms)}
.stat .ic{font-size:22px;margin-bottom:12px}.stat .l{color:var(--muted);font-size:13px}.stat .v{font-size:30px;font-weight:800;margin-top:8px}
@keyframes rise{from{opacity:0;transform:translateY(22px) scale(.97)}}
.panel{padding:20px;margin-bottom:20px}.panel:hover{transform:none}
.muted{color:var(--muted)}.small{font-size:12px}
.btn{border:0;border-radius:10px;padding:10px 15px;font-size:13px;font-weight:600;transition:.25s var(--ease);position:relative;overflow:hidden}
.btn:active{transform:scale(.95)}
.btn-primary{background:linear-gradient(135deg,#8b5cf6,#6d5dfc);color:#fff;box-shadow:0 6px 20px #8b5cf644}
.btn-primary:hover{box-shadow:0 8px 28px #8b5cf688;transform:translateY(-2px)}
.btn-primary::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,#ffffff44 50%,transparent 70%);transform:translateX(-120%)}
.btn-primary:hover::after{transform:translateX(120%);transition:transform .7s}
.btn-secondary{background:#ffffff0f;color:#e2e8f0;border:1px solid var(--border)}.btn-secondary:hover{background:#ffffff1c}
.btn-success{background:#14532d99;color:#86efac;border:1px solid #166534}.btn-success:hover{background:#166534}
.btn-danger{background:#451a1a99;color:#fca5a5;border:1px solid #7f1d1d}.btn-danger:hover{background:#7f1d1d}
.btn:disabled{opacity:.45;cursor:not-allowed}
.row{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
.news-grid,.post-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.news{overflow:hidden;display:flex;flex-direction:column;animation:rise .6s var(--ease) both;animation-delay:calc(var(--i,0)*60ms)}
.news-image{width:100%;height:170px;object-fit:cover;background:#1e293b;display:grid;place-items:center;color:#64748b;font-size:13px;transition:transform .6s var(--ease)}
.news:hover .news-image{transform:scale(1.05)}
.imgwrap{overflow:hidden}
.nc{padding:17px;display:flex;flex-direction:column;flex:1}
.src{color:#a78bfa;font-size:11px;font-weight:700;text-transform:uppercase;margin-bottom:8px}
.news h3,.post h3{font-size:16px;line-height:1.45;margin-bottom:9px}
.desc{color:var(--muted);font-size:13px;line-height:1.6;margin-bottom:12px}
.nc .row{margin-top:auto}
.field{margin-bottom:15px}.field label{display:block;color:#cbd5e1;font-size:13px;margin-bottom:8px}
.field input,.field textarea,.editor{width:100%;background:#0a1222;color:#fff;border:1px solid var(--border);border-radius:10px;padding:12px;outline:none;transition:.25s}
.field input:focus,.field textarea:focus,.editor:focus{border-color:var(--accent);box-shadow:0 0 0 4px #8b5cf626}
.editor{min-height:200px;resize:vertical;line-height:1.7}
.editor.writing{border-color:var(--accent)}
.badge{display:inline-block;border-radius:30px;padding:4px 10px;font-size:11px;font-weight:700;text-transform:uppercase}
.b-draft{background:#422d12;color:#fbbf24}.b-approved{background:#123d2a;color:#4ade80}.b-rejected{background:#451a1a;color:#fca5a5}
.b-scheduled{background:#2e1a54;color:#c4b5fd}.b-published{background:#172554;color:#93c5fd}
.tag{font-size:11px;color:var(--muted);margin-left:8px}
.post{padding:16px;animation:rise .5s var(--ease) both;animation-delay:calc(var(--i,0)*50ms)}
.post img{width:100%;max-height:180px;object-fit:cover;border-radius:10px;margin-bottom:12px}
.post p{color:var(--muted);font-size:13px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}
.when{margin-top:10px;font-size:12px;color:#c4b5fd}
.board{display:grid;grid-template-columns:repeat(4,minmax(250px,1fr));gap:16px;overflow-x:auto;padding-bottom:10px}
.col{background:#ffffff05;border:1px solid var(--border);border-radius:16px;padding:12px;min-height:300px}
.col-h{display:flex;justify-content:space-between;align-items:center;padding:6px 6px 12px;font-weight:700;font-size:14px}
.col-h span{background:#ffffff14;border-radius:20px;padding:2px 10px;font-size:12px}
.col .post{margin-bottom:12px}
.empty{color:var(--muted);text-align:center;padding:30px 15px;border:1px dashed var(--border);border-radius:14px;grid-column:1/-1;font-size:13px}
.loading{color:var(--muted);padding:25px;text-align:center;grid-column:1/-1}
.skel{height:300px;border-radius:16px;background:linear-gradient(100deg,#ffffff08 30%,#ffffff18 50%,#ffffff08 70%);background-size:200% 100%;animation:shim 1.2s infinite}
@keyframes shim{to{background-position:-200% 0}}
.photo-preview{display:none;max-width:100%;max-height:240px;border-radius:12px;margin-top:12px}
.overlay{position:fixed;inset:0;background:#02050cc4;backdrop-filter:blur(8px);z-index:500;display:none;padding:20px;overflow-y:auto}
.overlay.show{display:block;animation:fade .3s}
@keyframes fade{from{opacity:0}}
.modal{max-width:720px;margin:6vh auto;background:#0f1729;border:1px solid var(--border);border-radius:20px;padding:24px;box-shadow:0 30px 80px #000a;animation:modal .5s var(--spring)}
@keyframes modal{from{opacity:0;transform:translateY(40px) scale(.92)}}
.modal.sm{max-width:430px}
.quick{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
#pop{position:fixed;inset:0;z-index:900;display:none;place-items:center;pointer-events:none}
#pop.show{display:grid}
.pop-card{background:linear-gradient(160deg,#1b2742,#0f1729);border:1px solid #8b5cf688;border-radius:24px;padding:34px 44px;text-align:center;box-shadow:0 0 80px #8b5cf655,0 30px 80px #000a;animation:popIn .6s var(--spring) both}
.pop-card.out{animation:popOut .4s var(--ease) forwards}
@keyframes popIn{from{opacity:0;transform:scale(.5) translateY(30px)}}
@keyframes popOut{to{opacity:0;transform:scale(.9) translateY(-20px)}}
.pop-card h3{font-size:22px;margin:14px 0 6px}.pop-card p{color:var(--muted);font-size:14px}
.check{width:84px;height:84px;margin:auto}
.check circle{fill:#22c55e22;stroke:#22c55e;stroke-width:3;stroke-dasharray:252;stroke-dashoffset:252;animation:draw .7s .1s var(--ease) forwards;transform-origin:center}
.check path{fill:none;stroke:#4ade80;stroke-width:5;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:60;stroke-dashoffset:60;animation:draw .5s .6s var(--ease) forwards}
@keyframes draw{to{stroke-dashoffset:0}}
#confetti{position:fixed;inset:0;z-index:950;pointer-events:none}
.toast{position:fixed;bottom:24px;right:24px;background:#18233b;border:1px solid #475569;border-radius:12px;padding:14px 18px;max-width:360px;font-size:13px;z-index:1000;transform:translateX(130%);transition:transform .5s var(--spring);overflow:hidden}
.toast.show{transform:none}.toast.error{border-color:var(--red)}.toast.success{border-color:var(--green)}
.toast::after{content:"";position:absolute;left:0;bottom:0;height:3px;width:100%;background:currentColor;opacity:.5;transform-origin:left}
.toast.show::after{animation:bar 3.8s linear forwards}
@keyframes bar{to{transform:scaleX(0)}}
@keyframes pop{from{transform:scale(0)}}
@media(max-width:1050px){.grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:760px){.sidebar{width:70px;padding:18px 8px}.logo{justify-content:center;padding:0 0 22px}.logo h2,.nav-btn span:last-of-type,.nav-label,.sidebar-footer,.nav-btn b{display:none}.nav-btn{justify-content:center;font-size:19px}.main{margin-left:70px;width:calc(100% - 70px);padding:20px 14px}.news-grid,.post-list{grid-template-columns:1fr}.status-pill{display:none}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-delay:0s!important;transition-duration:.01ms!important}.aurora i{animation:none}}
</style>
<style id="scifi">
:root{--bg:#02040d;--panel:rgba(8,16,36,.66);--border:rgba(34,211,238,.24);--accent:#22d3ee;--accent2:#e879f9;--muted:#8fa6c4}
body{background:radial-gradient(ellipse at 50% -10%,#0b1d4a 0%,#02040d 62%)}
body::before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;background:repeating-linear-gradient(0deg,rgba(255,255,255,.025) 0 1px,transparent 1px 3px)}
.aurora i:nth-child(1){background:#0891b2}.aurora i:nth-child(2){background:#7c3aed}.aurora i:nth-child(3){background:#e11d48}
.app{position:relative;z-index:1}
.floor{position:fixed;left:-50%;right:-50%;bottom:0;height:46vh;z-index:0;pointer-events:none;background:linear-gradient(rgba(34,211,238,.2) 1px,transparent 1px),linear-gradient(90deg,rgba(34,211,238,.2) 1px,transparent 1px);background-size:64px 64px;transform:perspective(520px) rotateX(64deg);transform-origin:bottom;-webkit-mask-image:linear-gradient(to top,#000,transparent);mask-image:linear-gradient(to top,#000,transparent);animation:grid 5s linear infinite}
@keyframes grid{to{background-position:0 64px}}
h1,h2,.logo h2,.stat .v,.pop-card h3,.nav-label{font-family:Orbitron,"Plus Jakarta Sans",sans-serif;letter-spacing:.05em}
.topbar h1{background:linear-gradient(90deg,#fff,#67e8f9 55%,#e879f9);-webkit-background-clip:text;background-clip:text;color:transparent;text-transform:uppercase;font-size:24px}
.sh h2{font-size:15px;text-transform:uppercase;color:#a5f3fc}
.stat .v{color:#67e8f9;text-shadow:0 0 18px rgba(34,211,238,.55)}
.sidebar{background:rgba(2,6,18,.82);border-right:1px solid var(--border);box-shadow:0 0 40px rgba(34,211,238,.08)}
.logo-icon{background:linear-gradient(135deg,#06b6d4,#7c3aed);box-shadow:0 0 26px #22d3ee88;border-radius:50%}
.nav-btn.active{background:linear-gradient(90deg,#22d3ee30,transparent)}
.nav-btn.active::before{background:var(--accent);box-shadow:0 0 14px var(--accent)}
.nav-btn b{background:var(--accent2)}
.card{border:0;border-radius:4px;background:linear-gradient(160deg,rgba(14,30,66,.72),rgba(4,10,26,.8));box-shadow:inset 0 0 0 1px var(--border);clip-path:polygon(14px 0,100% 0,100% calc(100% - 14px),calc(100% - 14px) 100%,0 100%,0 14px)}
.card:hover{border:0;box-shadow:inset 0 0 0 1px rgba(34,211,238,.6),inset 0 0 30px rgba(34,211,238,.08)}
.card::before{content:"";position:absolute;top:0;right:0;width:22px;height:22px;border-top:2px solid var(--accent);border-right:2px solid var(--accent);z-index:3;pointer-events:none}
.card::after{background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),#22d3ee26,transparent 70%)}
.imgwrap{position:relative}
.imgwrap::after{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(transparent 55%,rgba(2,4,13,.85)),repeating-linear-gradient(0deg,rgba(34,211,238,.08) 0 1px,transparent 1px 3px)}
.news-image{filter:saturate(1.15) contrast(1.05)}
.src{color:var(--accent);letter-spacing:.14em}
.btn{border-radius:3px;text-transform:uppercase;letter-spacing:.08em;font-size:11.5px}
.btn-primary{background:linear-gradient(135deg,#0891b2,#7c3aed);box-shadow:0 0 20px #22d3ee44}
.btn-primary:hover{box-shadow:0 0 30px #22d3ee99}
.field input:focus,.field textarea:focus,.editor:focus{border-color:var(--accent);box-shadow:0 0 0 4px #22d3ee26}
.field input,.field textarea,.editor{background:#050d1f;border-radius:4px}
.modal{background:linear-gradient(160deg,#0b1633,#050b1c);border:1px solid rgba(34,211,238,.4);border-radius:6px;box-shadow:0 0 60px rgba(34,211,238,.18),0 30px 80px #000a}
.pop-card{border-color:#22d3ee88;box-shadow:0 0 80px #22d3ee55,0 30px 80px #000a}
.col{border-radius:6px}
.when{color:#67e8f9}
.status-pill{border-color:#0e7490;background:#06242d;color:#67e8f9}
.status-pill::before{background:#67e8f9}
.avatar{background:linear-gradient(135deg,#0891b2,#7c3aed)}
.main{padding-bottom:70px}
/* flying newspapers */
.sky{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;perspective:900px}
.paper{position:absolute;left:0;top:0;width:var(--w);height:calc(var(--w)*1.25);padding:calc(var(--w)*.08);border:1px solid rgba(125,240,255,.55);background:linear-gradient(145deg,rgba(34,211,238,.18),rgba(124,58,237,.14));box-shadow:0 0 26px rgba(34,211,238,.3),inset 0 0 18px rgba(34,211,238,.12);opacity:var(--o);filter:blur(var(--b));animation:fly var(--d) linear var(--dl) infinite;will-change:transform}
.paper b{display:block;font:700 calc(var(--w)*.1)/1.2 Orbitron,sans-serif;color:#b6f4ff;border-bottom:1px solid rgba(125,240,255,.6);padding-bottom:4px;margin-bottom:6px;white-space:nowrap;overflow:hidden}
.paper i{display:block;height:calc(var(--w)*.34);margin-bottom:6px;background:linear-gradient(135deg,rgba(232,121,249,.5),rgba(34,211,238,.4))}
.paper u{display:block;height:3px;margin:5px 0;background:rgba(182,244,255,.45)}
.paper u:nth-of-type(2){width:80%}.paper u:nth-of-type(4){width:60%}
@keyframes fly{0%{transform:translate3d(var(--x0),var(--y0),0) rotateZ(-8deg) rotateY(0) rotateX(20deg)}100%{transform:translate3d(var(--x1),var(--y1),0) rotateZ(22deg) rotateY(540deg) rotateX(-20deg)}}
/* multilingual breaking-news ticker */
.ticker{position:fixed;left:250px;right:0;bottom:0;height:36px;z-index:6;overflow:hidden;background:rgba(2,6,18,.9);border-top:1px solid var(--border);display:flex;align-items:center}
.ticker .tag2{flex:none;background:linear-gradient(90deg,#e11d48,#be123c);color:#fff;font:700 11px Orbitron,sans-serif;padding:0 16px;height:100%;display:grid;place-items:center;letter-spacing:.16em;z-index:1}
.ticker .track{display:flex;white-space:nowrap;animation:tick 70s linear infinite;color:#a5f3fc;font-size:12px;letter-spacing:.05em}
.ticker .track span{padding:0 24px}
.ticker .track span::before{content:"◆";color:#e879f9;margin-right:24px}
@keyframes tick{to{transform:translateX(-50%)}}
@media(max-width:760px){.ticker{left:70px}}
@media(prefers-reduced-motion:reduce){.sky,.floor{display:none}}
/* ===== Iron-Man HUD layer ===== */
:root{--gold:#fbbf24}
html{scrollbar-width:thin;scrollbar-color:#22d3ee55 transparent}
.sidebar{scrollbar-width:none;-ms-overflow-style:none;overflow-x:hidden;background-color:rgba(2,6,18,.84);background-image:linear-gradient(180deg,transparent,rgba(34,211,238,.13),transparent);background-size:100% 220px;background-repeat:no-repeat;animation:scanY 6s linear infinite,slideIn .9s var(--ease) both}
.sidebar::-webkit-scrollbar{display:none;width:0}
@keyframes scanY{from{background-position:0 -220px}to{background-position:0 110vh}}
@keyframes slideIn{from{transform:translateX(-100%);opacity:0}}
.reactor{position:relative;width:44px;height:44px;flex:none;border-radius:50%;background:radial-gradient(circle,#fff 0 12%,#7ff 14%,#06b6d4 38%,#0e3a52 62%,#021018 100%);box-shadow:0 0 22px #22d3eeaa,0 0 50px #22d3ee55;animation:beat 2.4s ease-in-out infinite}
.reactor i{position:absolute;inset:3px;border-radius:50%;border:2px dashed rgba(165,243,252,.85);animation:spin 6s linear infinite}
.reactor i:nth-child(2){inset:10px;border:2px solid rgba(34,211,238,.95);border-top-color:transparent;border-bottom-color:transparent;animation:spin 3s linear infinite reverse}
.reactor i:nth-child(3){inset:-6px;border:1px dotted rgba(251,191,36,.9);animation:spin 14s linear infinite}
.reactor b{position:absolute;inset:17px;border-radius:50%;background:#fff;box-shadow:0 0 14px #fff,0 0 28px #22d3ee}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes beat{50%{box-shadow:0 0 34px #22d3ee,0 0 80px #22d3ee88}}
.logo{gap:14px}
.logo h2{font-size:15px;line-height:1.15;letter-spacing:.06em;text-transform:uppercase;color:#e0f2fe}
.logo h2 span{display:block;font-size:11px;letter-spacing:.34em;color:var(--gold);margin-top:4px;text-shadow:0 0 10px #fbbf2488}
.nav-label{color:#fbbf24b0}
.nav-btn{overflow:hidden;opacity:0;animation:navIn .7s var(--ease) forwards;animation-delay:calc(var(--n,0)*70ms + .35s)}
@keyframes navIn{from{opacity:0;transform:translateX(-26px)}to{opacity:1;transform:none}}
.nav-btn::after{content:"";position:absolute;inset:0;border-radius:10px;pointer-events:none;background:linear-gradient(110deg,transparent 30%,rgba(34,211,238,.28) 50%,transparent 70%);transform:translateX(-115%);transition:transform .7s var(--ease)}
.nav-btn:hover::after{transform:translateX(115%)}
.nav-btn span:first-child{display:inline-block;transition:transform .45s var(--spring),color .3s,text-shadow .3s}
.nav-btn:hover span:first-child{transform:scale(1.4) rotate(14deg);color:#67e8f9}
.nav-btn.active span:first-child{color:var(--gold);text-shadow:0 0 12px var(--gold)}
.sidebar-footer{background:rgba(34,211,238,.05);border-color:var(--border)}
.jarvis{display:flex;align-items:center;gap:8px;font:700 10px Orbitron,sans-serif;letter-spacing:.14em;color:#67e8f9;margin-bottom:10px}
.jarvis .dot{width:7px;height:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 10px #22c55e;animation:blink 1.4s infinite}
.bars{display:flex;align-items:flex-end;gap:3px;height:26px;margin-top:12px}
.bars i{flex:1;height:100%;background:linear-gradient(#22d3ee,#0891b2);transform-origin:bottom;animation:eq 1.2s ease-in-out infinite}
.bars i:nth-child(2){animation-delay:-.2s}.bars i:nth-child(3){animation-delay:-.45s}.bars i:nth-child(4){animation-delay:-.7s}.bars i:nth-child(5){animation-delay:-.35s}.bars i:nth-child(6){animation-delay:-.9s}
@keyframes eq{0%,100%{transform:scaleY(.15)}50%{transform:scaleY(1)}}
.sh h2::before{content:"";display:inline-block;width:8px;height:8px;margin-right:10px;background:var(--gold);box-shadow:0 0 10px var(--gold);transform:rotate(45deg)}
#net{position:fixed;inset:0;z-index:0;pointer-events:none}
.hud{position:fixed;right:-14vh;top:50%;width:74vh;height:74vh;margin-top:-37vh;z-index:0;pointer-events:none;opacity:.4}
.hud i{position:absolute;inset:0;border-radius:50%;border:1px dashed rgba(34,211,238,.6);animation:spin 45s linear infinite}
.hud i:nth-child(2){inset:9%;border:6px double rgba(251,191,36,.55);border-left-color:transparent;border-right-color:transparent;animation:spin 26s linear infinite reverse}
.hud i:nth-child(3){inset:19%;border:0;background:repeating-conic-gradient(rgba(34,211,238,.7) 0 1deg,transparent 1deg 6deg);-webkit-mask:radial-gradient(circle,transparent 66%,#000 67%,#000 74%,transparent 75%);mask:radial-gradient(circle,transparent 66%,#000 67%,#000 74%,transparent 75%);animation:spin 70s linear infinite}
.hud i:nth-child(4){inset:34%;border:2px dotted rgba(232,121,249,.7);animation:spin 18s linear infinite reverse}
.hud::after{content:"";position:absolute;inset:19%;border-radius:50%;background:conic-gradient(from 0deg,transparent 0 290deg,rgba(34,211,238,.45) 360deg);animation:spin 5s linear infinite}
.beam{position:fixed;left:0;right:0;top:-160px;height:160px;z-index:0;pointer-events:none;background:linear-gradient(transparent,rgba(34,211,238,.08),transparent);animation:beam 8s linear infinite}
@keyframes beam{to{top:100%}}
.frame{position:fixed;inset:10px 10px 46px 262px;z-index:7;pointer-events:none}
.frame i{position:absolute;width:30px;height:30px;border:2px solid rgba(251,191,36,.8);filter:drop-shadow(0 0 4px #fbbf24)}
.frame i:nth-child(1){top:0;left:0;border-right:0;border-bottom:0}.frame i:nth-child(2){top:0;right:0;border-left:0;border-bottom:0}
.frame i:nth-child(3){bottom:0;left:0;border-right:0;border-top:0}.frame i:nth-child(4){bottom:0;right:0;border-left:0;border-top:0}
@media(max-width:760px){.frame{left:82px}}
.card:hover{transform:perspective(900px) translateY(-6px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg))}
.card.panel:hover{transform:none}
/* flying LinkedIn / news / photo objects */
.chip{position:absolute;left:0;top:0;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#fff;font-family:Orbitron,sans-serif;opacity:var(--o);filter:blur(var(--b));animation:fly var(--d) linear var(--dl) infinite;will-change:transform}
.chip::before{content:"";position:absolute;right:100%;top:50%;width:150px;height:2px;background:linear-gradient(90deg,transparent,rgba(34,211,238,.85))}
.chip.li{width:var(--w);height:var(--w);border-radius:18%;background:linear-gradient(145deg,#0a66c2,#0ea5e9);border:1px solid #7dd3fc;box-shadow:0 0 30px #0a66c2aa,inset 0 0 12px #ffffff55;font:900 calc(var(--w)*.5)/1 Arial,sans-serif}
.chip.nl{width:calc(var(--w)*1.7);padding:10px;align-items:stretch;border-radius:8px;background:rgba(10,102,194,.24);border:1px solid #38bdf8;box-shadow:0 0 24px #0a66c288;font-size:calc(var(--w)*.13)}
.chip.nl b{display:flex;align-items:center;gap:6px;letter-spacing:.1em}
.chip.nl em{font:900 1em Arial,sans-serif;background:#0a66c2;border-radius:3px;padding:1px 5px}
.chip.nl u{display:block;height:3px;margin-top:5px;background:rgba(186,230,253,.6)}
.chip.ph{width:calc(var(--w)*1.3);height:var(--w);border-radius:6px;border:2px solid #f0abfc;background:radial-gradient(circle at 72% 30%,#fde68a 0 9%,transparent 10%),linear-gradient(transparent 58%,#1e1b4b 58%),linear-gradient(#7c3aed,#db2777);box-shadow:0 0 26px #e879f988;font-size:calc(var(--w)*.1);letter-spacing:.12em;justify-content:flex-end;padding-bottom:4px}
.chip.ph span{font-size:calc(var(--w)*.34);margin-bottom:2px}
/* boot screen */
#boot{position:fixed;inset:0;z-index:2000;background:radial-gradient(circle at 50% 45%,#07203a,#01030a 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;transition:opacity .9s,transform .9s}
#boot.gone{opacity:0;transform:scale(1.25);pointer-events:none}
#boot .reactor{transform:scale(2.6);margin-bottom:46px}
#boot h2{font-size:22px;letter-spacing:.35em;color:#e0f2fe;text-transform:uppercase;text-align:center}
#boot p{font:600 12px Orbitron,sans-serif;letter-spacing:.25em;color:var(--gold);min-height:16px;text-align:center}
.loadbar{width:min(320px,70vw);height:3px;background:#0b2a3d;overflow:hidden}
.loadbar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#22d3ee,#fbbf24);box-shadow:0 0 12px #22d3ee;animation:load 2.4s ease-out forwards}
@keyframes load{to{width:100%}}
@media(prefers-reduced-motion:reduce){.hud,.beam,#net,#boot{display:none}}
/* ===== Admin-dashboard look (glass, soft cards, kanban) ===== */
:root{--accent:#3b82f6}
.hud{opacity:.18}.frame{display:none}.floor{opacity:.45}
.orb{position:fixed;border-radius:50%;z-index:0;pointer-events:none}
.orb.o1{top:-110px;right:14%;width:230px;height:230px;background:radial-gradient(circle at 35% 30%,#fde68a,#f59e0b 45%,#92400e 85%);box-shadow:0 0 120px #f59e0b55;animation:orbf 10s ease-in-out infinite alternate}
.orb.o2{bottom:-120px;right:6%;width:300px;height:300px;background:radial-gradient(circle at 35% 30%,#5eead4,#0d9488 55%,#134e4a 90%);box-shadow:0 0 140px #14b8a655;animation:orbf 12s ease-in-out infinite alternate-reverse}
@keyframes orbf{to{transform:translate(-30px,26px) scale(1.06)}}
.sh h2,.topbar h1,.stat .v{font-family:"Plus Jakarta Sans",sans-serif;text-transform:none;letter-spacing:-.02em}
.topbar h1{background:none;-webkit-text-fill-color:#fff;color:#fff;font-size:30px;font-weight:800}
.sh h2{font-size:17px;color:#fff}.sh h2::before{display:none}
.stat .v{color:#fff;text-shadow:none}
.greet{display:flex;align-items:center;gap:8px;color:#8fa6c4;font-size:12px;margin-bottom:6px}
.gdot{width:7px;height:7px;border-radius:50%;background:#22c55e;box-shadow:0 0 10px #22c55e}
.nav-label{font-family:"Plus Jakarta Sans",sans-serif;letter-spacing:.14em;color:#64748b}
.nav-btn{border-radius:12px}
.nav-btn.active{background:linear-gradient(135deg,#2563eb,#3b82f6);color:#fff;box-shadow:0 8px 24px #2563eb55}
.nav-btn.active::before{display:none}
.nav-btn.active span:first-child{color:#fff;text-shadow:none}
.card{clip-path:none;border-radius:18px;background:linear-gradient(160deg,rgba(20,30,56,.72),rgba(8,14,30,.78));box-shadow:inset 0 0 0 1px rgba(255,255,255,.07);backdrop-filter:blur(18px)}
.card::before{display:none}
.card:hover{box-shadow:inset 0 0 0 1px rgba(96,165,250,.5),0 16px 40px rgba(0,0,0,.35)}
.btn{text-transform:none;letter-spacing:0;border-radius:10px;font-size:12.5px}
.btn-primary{background:linear-gradient(135deg,#2563eb,#3b82f6);box-shadow:0 6px 20px #2563eb55}
.btn-primary:hover{box-shadow:0 8px 28px #3b82f6aa}
.src{color:#60a5fa;letter-spacing:.1em}
.search{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.09);border-radius:12px;padding:0 12px;height:38px;transition:.3s var(--ease)}
.search:focus-within{border-color:#3b82f6;box-shadow:0 0 0 4px #3b82f626;width:260px}
.search span{color:#94a3b8;font-size:17px}
.search input{background:none;border:0;outline:0;color:#fff;width:150px;font-size:13px;transition:width .3s}
.search:focus-within input{width:200px}
.side-toggle{display:flex;justify-content:space-between;align-items:center;margin-top:22px;padding:10px 12px;color:#9caec5;font-size:13px}
.sw{position:relative;width:38px;height:22px;cursor:pointer}.sw input{display:none}
.sw i{position:absolute;inset:0;border-radius:20px;background:#334155;transition:.3s}
.sw i::after{content:"";position:absolute;top:3px;left:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:transform .35s var(--spring)}
.sw input:checked+i{background:#22c55e}.sw input:checked+i::after{transform:translateX(16px)}
.usercard{display:flex;gap:10px;align-items:center;margin:4px 0 14px;padding:10px 12px;border:1px solid rgba(255,255,255,.07);border-radius:14px;background:rgba(255,255,255,.04)}
.usercard b{display:block;font-size:13px}.usercard small{color:#8fa6c4;font-size:11px}
.board{gap:18px}
.col{background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.07);border-radius:20px;padding:14px;transition:background .25s,box-shadow .25s}
.col.over{background:rgba(59,130,246,.09);box-shadow:0 0 0 2px #3b82f6 inset}
.col-h{padding:2px 2px 14px;align-items:flex-start}
.col-h>div{font-size:14px;display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.col-h small{flex-basis:100%;color:#8fa6c4;font-weight:500;font-size:11.5px;margin-left:16px}
.dot{width:8px;height:8px;border-radius:50%;display:inline-block}
.d-Draft{background:#f59e0b;box-shadow:0 0 8px #f59e0b}.d-Approved{background:#22c55e;box-shadow:0 0 8px #22c55e}
.d-Scheduled{background:#a78bfa;box-shadow:0 0 8px #a78bfa}.d-Published{background:#3b82f6;box-shadow:0 0 8px #3b82f6}
.col .post{padding:12px;border-radius:14px;cursor:grab;transition:transform .3s var(--spring),opacity .2s,box-shadow .3s}
.col .post:active{cursor:grabbing}
.col .post img{max-height:96px;pointer-events:none}
.col .post p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.col .post h3{font-size:14px}
.post.dragging{opacity:.45;transform:scale(1.04) rotate(-2deg)!important}
.col .empty{border-radius:14px;padding:26px 10px}
/* ===== Theme switch button (both themes) ===== */
.rail-btn{display:flex;gap:12px;align-items:center;width:100%;border:0;background:transparent;color:#9caec5;padding:11px 12px;border-radius:12px;font-size:14px;margin-top:10px;transition:.25s var(--ease)}
.rail-btn:hover{background:#ffffff0f;color:#fff}.rail-btn em{font-style:normal}
.pillnav{display:none}
body,.card{transition:background-color .5s,color .5s}
/* ===== MINIMAL LIGHT THEME (like the "Manage" dashboard) ===== */
body.minimal{--muted:#6b7280;--border:#e6e8ee;background:#eef0f4;color:#0f172a}
body.minimal::before,body.minimal .aurora,body.minimal .floor,body.minimal #net,body.minimal .hud,body.minimal .beam,body.minimal .orb,body.minimal .sky,body.minimal .frame,body.minimal #boot,body.minimal .ticker{display:none}
html:has(body.minimal){scrollbar-color:#cbd5e1 transparent}
/* left icon rail */
body.minimal .sidebar{width:64px;padding:16px 8px;background:#fff;border-right:1px solid #e8eaf0;box-shadow:none;animation:none;background-image:none;backdrop-filter:none}
body.minimal .logo{justify-content:center;padding:0 0 18px}
body.minimal .logo h2,body.minimal .nav-label,body.minimal .sidebar-footer,body.minimal .nav-btn span:last-of-type,body.minimal .nav-btn b,body.minimal .side-toggle span,body.minimal .rail-btn em,body.minimal .usercard>div:last-child{display:none}
body.minimal .reactor{width:38px;height:38px;border-radius:12px;background:#0f172a;box-shadow:none;animation:none}
body.minimal .reactor i,body.minimal .reactor b{display:none}
body.minimal .reactor::after{content:"in";display:grid;place-items:center;height:100%;color:#fff;font:800 17px Arial,sans-serif}
body.minimal .nav-btn{justify-content:center;padding:12px 0;font-size:17px;color:#6b7280;opacity:1;animation:none;border-radius:12px}
body.minimal .nav-btn:hover{background:#f1f3f7;color:#0f172a;transform:none}
body.minimal .nav-btn::after{display:none}
body.minimal .nav-btn.active{background:#0f172a;color:#fff;box-shadow:0 6px 16px rgba(15,23,42,.25)}
body.minimal .nav-btn.active span:first-child{color:#fff}
body.minimal .rail-btn{justify-content:center;padding:12px 0;color:#6b7280;font-size:17px}
body.minimal .rail-btn:hover{background:#f1f3f7;color:#0f172a}
body.minimal .side-toggle{justify-content:center;padding:12px 0}
body.minimal .usercard{justify-content:center;padding:8px 0;border:0;background:none;margin:0}
body.minimal .main{margin-left:64px;width:calc(100% - 64px);padding:22px 32px 40px}
/* top pill navigation */
body.minimal .pillnav{display:flex;gap:4px;width:max-content;max-width:100%;overflow-x:auto;scrollbar-width:none;margin-bottom:24px;padding:5px;background:#fff;border:1px solid #e6e8ee;border-radius:999px;box-shadow:0 1px 2px rgba(15,23,42,.04)}
body.minimal .pillnav::-webkit-scrollbar{display:none}
.pill{border:0;background:transparent;color:#4b5563;padding:8px 18px;border-radius:999px;font-size:13px;font-weight:600;white-space:nowrap;transition:background .3s var(--ease),color .3s,transform .3s var(--spring)}
.pill:hover{background:#f1f3f7;transform:translateY(-1px)}
.pill.active{background:#0f172a;color:#fff;box-shadow:0 4px 12px rgba(15,23,42,.25)}
/* page header + text */
body.minimal .topbar h1{-webkit-text-fill-color:#0f172a;color:#0f172a;font-size:28px}
body.minimal .sh h2,body.minimal .stat .v{color:#0f172a}
body.minimal .greet,body.minimal .topbar p{color:#6b7280}
body.minimal .field label{color:#374151}
/* cards */
body.minimal .card{background:#fff;backdrop-filter:none;border-radius:20px;box-shadow:0 1px 2px rgba(15,23,42,.04),0 0 0 1px #e8eaf0;transition:transform .35s var(--spring),box-shadow .35s,background-color .5s}
body.minimal .card:hover{transform:translateY(-5px);box-shadow:0 16px 36px rgba(15,23,42,.10),0 0 0 1px #dfe3ec}
body.minimal .card.panel:hover{transform:none;box-shadow:0 1px 2px rgba(15,23,42,.04),0 0 0 1px #e8eaf0}
body.minimal .card::after{background:radial-gradient(260px circle at var(--mx,50%) var(--my,50%),rgba(15,23,42,.045),transparent 70%)}
body.minimal .news-image{background:#e8ebf2;color:#9aa3b2;filter:none}
body.minimal .imgwrap::after{display:none}
body.minimal .src{color:#2563eb}
body.minimal .skel{background:linear-gradient(100deg,#0000000a 30%,#00000014 50%,#0000000a 70%);background-size:200% 100%}
/* buttons, inputs, badges */
body.minimal .btn-primary{background:#0f172a;color:#fff;box-shadow:0 6px 16px rgba(15,23,42,.22)}
body.minimal .btn-primary:hover{box-shadow:0 10px 24px rgba(15,23,42,.32)}
body.minimal .btn-secondary{background:#fff;color:#111827;border:1px solid #e3e6ee}
