body.minimal .b-draft{background:#fef3c7;color:#92400e}body.minimal .b-approved{background:#dcfce7;color:#166534}
body.minimal .b-rejected{background:#fee2e2;color:#991b1b}body.minimal .b-scheduled{background:#ede9fe;color:#5b21b6}
body.minimal .b-published{background:#dbeafe;color:#1e40af}
body.minimal .when{color:#6d28d9}
body.minimal .status-pill{background:#dcfce7;color:#166534;border-color:#bbf7d0}
