body.minimal .sw i{background:#d1d5db}body.minimal .sw input:checked+i{background:#22c55e}
/* kanban */
body.minimal .col{background:#f7f8fb;border-color:#e8eaf0}
body.minimal .col.over{background:#eff6ff;box-shadow:0 0 0 2px #3b82f6 inset}
body.minimal .col-h span{background:#e8ebf2;color:#374151}
body.minimal .empty{border-color:#d9dde7;color:#6b7280}
body.minimal .post.dragging{box-shadow:0 20px 40px rgba(15,23,42,.2)}
/* popups */
body.minimal .overlay{background:rgba(15,23,42,.45)}
body.minimal .modal{background:#fff;border-color:#e6e8ee;box-shadow:0 30px 80px rgba(15,23,42,.25)}
