<script>
/* ============ 1. n8n WEBHOOKS ============ */
const DEFAULT_PUBLISH = "https://unknown1212.app.n8n.cloud/webhook/publish-post";
const DEFAULT_NEWS_PUBLISH = "https://unknown1212.app.n8n.cloud/webhook/approve-news";
const store = k => { try { return localStorage.getItem(k); } catch { return null; } };

const API = {
  getNews: "https://unknown1212.app.n8n.cloud/webhook/get-news",
  processArticle: "https://unknown1212.app.n8n.cloud/webhook/process-article",
  /* PHOTO posts go here */
  publishPost: store("np_publish_url") || DEFAULT_PUBLISH,
  /* NEWS posts go here (this is your new approve-news webhook) */
  approveNews: store("np_news_publish_url") || DEFAULT_NEWS_PUBLISH
};

/* ============ 2. STATE ============ */
const $ = s => document.querySelector(s);
const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
let news = [], posts = [], selected = null, resumeUrl = null, schedId = null, toastT;
const KEY = "neuralpost_posts_v2";

function load(){ try{ posts = JSON.parse(localStorage.getItem(KEY) || "[]"); }catch{ posts = []; } }
function save(){
  try{ localStorage.setItem(KEY, JSON.stringify(posts)); }
  catch{ toast("Browser storage is full. Delete old photo drafts.", "error"); }
  renderAll();
}
const find = id => posts.find(p => p.id === id);
const uid = () => crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random());

/* ============ 3. FEEDBACK ============ */
function toast(msg, type = ""){
  const t = $("#toast"); t.textContent = msg; t.className = "toast";
  void t.offsetWidth; t.className = "toast show " + type;
  clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove("show"), 3800);
}
function celebrate(title, sub){
  $("#popCard").className = "pop-card";
  $("#popCard").innerHTML = `<svg class="check" viewBox="0 0 84 84"><circle cx="42" cy="42" r="40"/><path d="M26 44l11 11 22-24"/></svg><h3>${esc(title)}</h3><p>${esc(sub)}</p>`;
  $("#pop").classList.add("show");
  confetti();
  setTimeout(() => $("#popCard").classList.add("out"), 1900);
  setTimeout(() => $("#pop").classList.remove("show"), 2300);
}
function confetti(){
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  const c = $("#confetti"), x = c.getContext("2d");
  c.width = innerWidth; c.height = innerHeight;
  const colors = ["#8b5cf6","#38bdf8","#22c55e","#f59e0b","#ec4899"];
  const bits = Array.from({length:110}, () => ({
    x:innerWidth/2,y:innerHeight/2.2,r:Math.random()*6+3,
    vx:(Math.random()-.5)*16,vy:Math.random()*-15-3,rot:Math.random()*6,
    c:colors[Math.floor(Math.random()*colors.length)]
  }));
  let f=0;
  (function tick(){
    x.clearRect(0,0,c.width,c.height);
    bits.forEach(b=>{
      b.vy+=.45;b.x+=b.vx;b.y+=b.vy;b.rot+=.15;
      x.save();x.translate(b.x,b.y);x.rotate(b.rot);x.fillStyle=b.c;
      x.globalAlpha=Math.max(0,1-f/110);x.fillRect(-b.r,-b.r/2,b.r*2,b.r);x.restore();
    });
    if(++f<120)requestAnimationFrame(tick);else x.clearRect(0,0,c.width,c.height);
  })();
}
function typewrite(el,text){
  el.classList.add("writing");el.value="";
  const step=Math.max(1,Math.ceil(text.length/90));let i=0;
  const t=setInterval(()=>{
    i+=step;el.value=text.slice(0,i);el.scrollTop=el.scrollHeight;
    if(i>=text.length){clearInterval(t);el.value=text;el.classList.remove("writing");}
  },16);
}
function countUp(el,to){
  const from=+el.textContent||0;if(from===to){el.textContent=to;return;}
  const t0=performance.now();
  (function f(t){const k=Math.min(1,(t-t0)/600);
    el.textContent=Math.round(from+(to-from)*(1-Math.pow(1-k,3)));
    if(k<1)requestAnimationFrame(f);
  })(t0);
}
document.addEventListener("pointermove",e=>{
  const c=e.target.closest?.(".card");if(!c)return;
  const r=c.getBoundingClientRect();
  c.style.setProperty("--mx",(e.clientX-r.left)+"px");
  c.style.setProperty("--my",(e.clientY-r.top)+"px");
});

/* ============ 4. NAVIGATION ============ */
const info={
  dashboard:["Dashboard","Manage your AI-powered LinkedIn content."],
  news:["NewsFeed","Discover articles and generate LinkedIn captions."],
  drafts:["Post Drafts","Track every post from draft to published."],
  photos:["Photo Posts","Prepare image-based LinkedIn content."],
  approval:["Approval Centre","Review content before publishing."],
  scheduled:["Scheduled Posts","Your automatic publishing queue."],
  published:["Published Posts","Your published content."],
  settings:["Settings","Connect your n8n publishing workflow."]
};
function showPage(n){
  document.querySelectorAll(".page").forEach(p=>p.classList.remove("active"));
  document.querySelectorAll(".nav-btn").forEach(b=>b.classList.toggle("active",b.dataset.page===n));
  $("#page-"+n).classList.add("active");
  $("#pageTitle").textContent=info[n][0];
  $("#pageSubtitle").textContent=info[n][1];
}
document.querySelectorAll(".nav-btn").forEach(b=>b.onclick=()=>showPage(b.dataset.page));
const openModal=id=>$("#"+id).classList.add("show");
const closeModal=id=>$("#"+id).classList.remove("show");

/* ============ 5. NEWS ============ */
const g=(a,...k)=>{
  for(const x of k){const v=x.split(".").reduce((o,p)=>o?.[p],a);if(v)return v;}
  return "";
};
/* Finds an image for an article: known fields first, then any image link hidden inside the article data */
function getImage(a){
  const direct=g(a,"image","image_url","imageUrl","urlToImage","thumbnail","enclosure.url","enclosure.link",
    "media:content.$.url","media:content.url","media:thumbnail.$.url","media:thumbnail.url",
    "itunes.image","og:image","ogImage");
  if(typeof direct==="string"&&direct.startsWith("http"))return direct;
  const text=JSON.stringify(a||{});
  const tag=text.match(/<img[^>]+src=\\?["'](https?:[^"'\\]+)/i);
  if(tag)return tag[1];
  const file=text.match(/https?:\/\/[^"'\s<>\\]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\s<>\\]*)?/i);
  return file?file[0]:"";
}
function newsCard(a,i){
  const img=getImage(a);
  const url=g(a,"link","url","article_url");
  return `<article class="card news" style="--i:${i}">
    <div class="imgwrap">${img?`<img class="news-image" src="${esc(img)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.outerHTML='<div class=&quot;news-image&quot;>No image</div>'">`:`<div class="news-image">No image</div>`}</div>
    <div class="nc"><div class="src">${esc(g(a,"creator","dc:creator","source")||"AI News")}</div>
    <h3>${esc(g(a,"title","headline","name")||"Untitled article")}</h3>
    <p class="desc">${esc(g(a,"contentSnippet","description","content","summary")||"No description.").slice(0,260)}</p>
    <div class="row"><button class="btn btn-primary" data-gen="${i}">✨ Generate Caption</button>
    ${url?`<button class="btn btn-secondary" data-read="${i}">Read Article</button>`:""}</div></div></article>`;
}
function renderNews(){
  $("#newsGrid").innerHTML=news.length?news.map(newsCard).join(""):'<div class="empty">No articles returned by n8n.</div>';
  $("#dashboardNews").innerHTML=news.length?news.slice(0,4).map(newsCard).join(""):'<div class="empty">No news yet. Refresh the feed.</div>';
  renderStats();
}
async function loadNews(){
  const btn=$("#refreshNewsBtn"),sk='<div class="skel"></div><div class="skel"></div>';
  $("#newsGrid").innerHTML=sk;$("#dashboardNews").innerHTML=sk;
  btn.disabled=true;btn.textContent="Loading...";
  try{
    const r=await fetch(API.getNews);if(!r.ok)throw new Error("News webhook returned HTTP "+r.status);
    const d=await r.json();
    news=Array.isArray(d)?d:(d.articles||d.data||d.items);
    if(!Array.isArray(news)){news=[];throw new Error("get-news did not return an array.");}
    renderNews();toast("News loaded.","success");
  }catch(e){
    $("#newsGrid").innerHTML=$("#dashboardNews").innerHTML=`<div class="empty">${esc(e.message)}</div>`;
    toast("Could not load news: "+e.message,"error");
  }finally{btn.disabled=false;btn.textContent="↻ Refresh News";}
}
document.addEventListener("click",e=>{
  const gen=e.target.closest("[data-gen]"),rd=e.target.closest("[data-read]");
  if(gen)generate(+gen.dataset.gen);
  if(rd){const u=g(news[+rd.dataset.read],"link","url","article_url");if(u)open(u,"_blank","noopener,noreferrer");}
});

/* ============ 6. GENERATE CAPTION ============ */
async function generate(i){
  selected=news[i];if(!selected)return;
  resumeUrl=null;
  $("#modalTitle").textContent=g(selected,"title","headline","name");
  const box=$("#genCaption");
  box.value="✨ AI is writing your caption...";box.classList.add("writing");
  openModal("captionModal");
  try{
    const r=await fetch(API.processArticle,{
      method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({article:selected})
    });
    if(!r.ok)throw new Error("Caption webhook returned HTTP "+r.status);
    const d=await r.json();
    const cap=d.caption||d.ai_caption||d.output||d.text||"";
    if(!cap)throw new Error("No caption returned. Check process-article output in n8n.");
    resumeUrl=d.resumeUrl||d.resume_url||d.approvalUrl||d.approval_url||null;
    celebrate("Caption generated!","Your LinkedIn post is ready to review.");
    setTimeout(()=>typewrite(box,cap),500);
  }catch(err){
    box.value="";box.classList.remove("writing");
    toast("Caption failed: "+err.message,"error");
  }
}
function modalPost(status){
  const caption=$("#genCaption").value.trim();
  if(!caption){toast("There is no caption yet.","error");return null;}
  const p={
    id:uid(),type:"news",
    title:g(selected,"title","headline","name")||"LinkedIn news post",
    caption,article:selected,resumeUrl,status,createdAt:new Date().toISOString()
  };
  posts.unshift(p);return p;
}
async function decide(approved){
  if(!resumeUrl)return true;
  try{
    const u=new URL(resumeUrl);u.searchParams.set("approved",approved);
    const r=await fetch(u);if(!r.ok)throw new Error("HTTP "+r.status);
    return true;
  }catch(e){toast("n8n approval failed: "+e.message,"error");return false;}
}
document.querySelectorAll("[data-modal]").forEach(b=>b.onclick=async()=>{
  const a=b.dataset.modal;
  if(a==="copy"){
    try{await navigator.clipboard.writeText($("#genCaption").value);toast("Caption copied.","success");}
    catch{toast("Copy failed. Select the text manually.","error");}
    return;
  }
  if(a==="save"){
    if(modalPost("draft")){save();closeModal("captionModal");toast("Draft saved.","success");showPage("drafts");}
    return;
  }
  const ok=await decide(a==="approve");if(!ok)return;
  if(modalPost(a==="approve"?"approved":"rejected")){
    save();closeModal("captionModal");
    if(a==="approve"){celebrate("Approved!","Schedule it from the Post Drafts board.");showPage("drafts");}
    else toast("Post rejected.");
  }
});

/* ============ 7. PHOTO POSTS ============ */
function compress(file){
  return new Promise((res,rej)=>{
    const img=new Image(),url=URL.createObjectURL(file);
    img.onload=()=>{
      const k=Math.min(1,1280/Math.max(img.width,img.height)),c=document.createElement("canvas");
      c.width=img.width*k;c.height=img.height*k;
      c.getContext("2d").drawImage(img,0,0,c.width,c.height);
      URL.revokeObjectURL(url);res(c.toDataURL("image/jpeg",.82));
    };
    img.onerror=()=>rej(new Error("Could not read image"));
    img.src=url;
  });
}
$("#photoFile").onchange=async e=>{
  const f=e.target.files[0],pv=$("#photoPreview");
  if(!f){pv.style.display="none";return;}
  if(!f.type.startsWith("image/")){toast("Please choose an image.","error");e.target.value="";return;}
  try{pv.src=await compress(f);pv.style.display="block";}
  catch(err){toast(err.message,"error");}
};
$("#photoForm").onsubmit=e=>{
  e.preventDefault();
  const caption=$("#photoCaption").value.trim(),pv=$("#photoPreview");
  if(!caption)return toast("Please enter a caption.","error");
  if(!pv.src||pv.style.display==="none")return toast("Please select a photo.","error");
  posts.unshift({
    id:uid(),type:"photo",title:"Photo post",caption,
    image:pv.src,status:"draft",createdAt:new Date().toISOString()
  });
  save();e.target.reset();pv.style.display="none";
  celebrate("Photo draft saved!","Approve it to schedule or post.");
};

/* ============ 8. POST CARDS & ACTIONS ============ */
const fmt=d=>new Date(d).toLocaleString([],{dateStyle:"medium",timeStyle:"short"});
function actions(p){
  const b=(a,cls,t)=>`<button class="btn ${cls}" data-act="${a}" data-id="${p.id}">${t}</button>`;
  if(p.status==="draft"||p.status==="rejected")
    return b("approve","btn-success","✓ Approve")+(p.status==="draft"?b("reject","btn-danger","Reject"):"")+b("edit","btn-secondary","Edit")+b("del","btn-danger","Delete");
  if(p.status==="approved")
    return b("sched","btn-primary","◷ Schedule")+b("now","btn-secondary","Post now")+b("edit","btn-secondary","Edit")+b("del","btn-danger","Delete");
  if(p.status==="scheduled")
    return b("sched","btn-secondary","Reschedule")+b("unsched","btn-danger","Cancel schedule");
  return "";
}
function postCard(p,i){
  return `<div class="card post" draggable="true" data-pid="${p.id}" style="--i:${i}">
    ${p.image?`<img src="${esc(p.image)}" alt="">`:""}
    <span class="badge b-${p.status}">${p.status}</span><span class="tag">${p.type==="photo"?"Photo":"News"}</span>
    <h3 style="margin-top:10px">${esc(p.title)}</h3><p>${esc(p.caption)}</p>
    ${p.scheduledAt&&p.status==="scheduled"?`<div class="when">◷ Posts ${fmt(p.scheduledAt)}</div>`:""}
    ${p.publishedAt?`<div class="when">↗ Published ${fmt(p.publishedAt)}</div>`:""}
    <div class="row">${actions(p)}</div></div>`;
}
const list=(arr,msg)=>arr.length?arr.map(postCard).join(""):`<div class="empty">${msg}</div>`;
function renderAll(){
  const by=s=>posts.filter(p=>s.includes(p.status));
  const cols=[["Draft",["draft","rejected"]],["Approved",["approved"]],["Scheduled",["scheduled"]],["Published",["published"]]];
  $("#board").innerHTML=cols.map(([n,s])=>{
    const a=by(s);
    return `<div class="col" data-col="${n}"><div class="col-h"><div><i class="dot d-${n}"></i>${n}<small>${({Draft:"Waiting for review",Approved:"Ready to go live",Scheduled:"Queued to publish",Published:"Live on LinkedIn"})[n]}</small></div><span>${a.length}</span></div>${a.length?a.map(postCard).join(""):'<div class="empty">Drop a post here</div>'}</div>`;
  }).join("");
  $("#photoList").innerHTML=list(posts.filter(p=>p.type==="photo"),"No photo drafts yet.");
  $("#approvalList").innerHTML=list(by(["draft"]),"Nothing is waiting for approval.");
  $("#scheduledList").innerHTML=list(by(["scheduled"]).sort((a,b)=>new Date(a.scheduledAt)-new Date(b.scheduledAt)),"No scheduled posts yet. Approve a post, then schedule it.");
  $("#publishedList").innerHTML=list(by(["published"]),"No published posts yet.");
  [["#bDrafts",by(["draft"]).length],["#bApproval",by(["draft"]).length],["#bSched",by(["scheduled"]).length]].forEach(([s,n])=>{
    const el=$(s);el.textContent=n;el.classList.toggle("on",n>0);
  });
  renderStats();
}
function renderStats(){
  countUp($("#statNews"),news.length);
  countUp($("#statDrafts"),posts.length);
  countUp($("#statSched"),posts.filter(p=>p.status==="scheduled").length);
  countUp($("#statPub"),posts.filter(p=>p.status==="published").length);
}
document.addEventListener("click",async e=>{
  const b=e.target.closest("[data-act]");if(!b)return;
  const p=find(b.dataset.id);if(!p)return;
  const a=b.dataset.act;
  if(a==="approve"){
    if(p.resumeUrl){
      const old=resumeUrl;resumeUrl=p.resumeUrl;
      const ok=await decide(true);resumeUrl=old;if(!ok)return;
    }
    p.status="approved";save();
    celebrate("Approved!",p.type==="photo"?"Photo post approved. Schedule it next.":"Ready to schedule.");
  }
  if(a==="reject"){
    if(p.resumeUrl){
      const old=resumeUrl;resumeUrl=p.resumeUrl;
      const ok=await decide(false);resumeUrl=old;if(!ok)return;
    }
    p.status="rejected";save();toast("Post rejected.");
  }
  if(a==="edit"){
    const t=prompt("Edit caption:",p.caption);
    if(t&&t.trim()){p.caption=t.trim();save();toast("Caption updated.","success");}
  }
  if(a==="del"){
    if(confirm("Delete this post?")){posts=posts.filter(x=>x.id!==p.id);save();}
  }
  if(a==="unsched"){p.status="approved";delete p.scheduledAt;save();toast("Schedule cancelled.");}
  if(a==="now")publish(p);
  if(a==="sched"){
    schedId=p.id;const d=new Date(Date.now()+36e5);
    $("#schedTime").value=new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,16);
    openModal("schedModal");
