/* ---- Settings: webhook URLs ---- */
function showStatus(el,u,label){
  if(!u){el.style.color="#fbbf24";el.textContent="Not connected. Paste your webhook URL above.";}
  else if(u.includes("/webhook-test/")){el.style.color="#fbbf24";el.textContent="This is a Test URL. Use the Production URL instead.";}
  else{el.style.color="#4ade80";el.textContent=label+" connected to: "+u;}
}
function urlStatus(){
  $("#urlInput").value=API.publishPost;
  $("#newsUrlInput").value=API.approveNews;
  showStatus($("#urlStatus"),API.publishPost,"Photo posts");
  showStatus($("#newsUrlStatus"),API.approveNews,"News posts");
}
function saveUrl(inputId,storeKey,apiKey){
  const v=$(inputId).value.trim();
  if(v&&!/^https:\/\//.test(v))return toast("The URL must start with https://","error");
  if(v&&!v.includes("/webhook/"))return toast("Use the n8n Production URL containing /webhook/.","error");
  try{localStorage.setItem(storeKey,v);}catch{}
  API[apiKey]=v;urlStatus();
  toast(v?"Webhook URL saved.":"Webhook URL cleared.","success");
}
$("#urlSave").onclick=()=>saveUrl("#urlInput","np_publish_url","publishPost");
$("#newsUrlSave").onclick=()=>saveUrl("#newsUrlInput","np_news_publish_url","approveNews");

/* ---- Publishing: news -> approve-news, photo -> publish-post ---- */
async function publish(p){
  const target = p.type==="news" ? API.approveNews : API.publishPost;
  if(!target){
    toast(p.type==="news"
      ? "Paste your n8n approve-news webhook URL in Settings first."
      : "Paste your n8n publish webhook URL in Settings first.","error");
    showPage("settings");
    if(p.status==="scheduled"||p.status==="publishing"){p.status="approved";save();}
    return;
  }
  if(p.isPublishing)return;
  p.isPublishing=true;
  try{
    const r=await fetch(target,{
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify({
        type:p.type,
        title:p.title||"",
        caption:p.caption,
        article:p.article||null,
        image:p.image||null
      })
    });
    if(!r.ok)throw new Error("HTTP "+r.status);
    p.status="published";
    p.publishedAt=new Date().toISOString();
    delete p.scheduledAt;
    save();
    celebrate("Published!","Your post was accepted by the n8n webhook.");
  }catch(e){
    toast("Publish failed: "+(e.message==="Failed to fetch"?"Failed to fetch. Check n8n CORS and webhook settings.":e.message),"error");
    if(p.status==="scheduled"||p.status==="publishing"){p.status="approved";save();}
  }finally{
    p.isPublishing=false;
  }
}
function tick(){
  posts.filter(p=>p.status==="scheduled"&&new Date(p.scheduledAt)<=new Date())
    .forEach(p=>{p.status="publishing";publish(p);});
}
setInterval(tick,15000);

/* ============ 10. START ============ */
load();renderAll();urlStatus();showPage("dashboard");loadNews();tick();
