<script>
/* ===== Smooth click sounds (Web Audio, no files needed) ===== */
window.Snd=(function(){
  let ctx,master,on=true;
  try{on=localStorage.getItem("np_sound")!=="off";}catch{}
  function init(){
    if(!ctx){
      const A=window.AudioContext||window.webkitAudioContext;if(!A)return false;
      ctx=new A();master=ctx.createGain();master.gain.value=.55;
      const lp=ctx.createBiquadFilter();lp.type="lowpass";lp.frequency.value=5200;
      const dl=ctx.createDelay();dl.delayTime.value=.13;const fb=ctx.createGain();fb.gain.value=.22;
      master.connect(lp);lp.connect(ctx.destination);
      lp.connect(dl);dl.connect(fb);fb.connect(dl);dl.connect(ctx.destination);
    }
    if(ctx.state==="suspended")ctx.resume();
    return true;
  }
  function tone(f,t0,d,type,v,f2){
    const t=ctx.currentTime+t0,o=ctx.createOscillator(),g=ctx.createGain();
    o.type=type||"sine";o.frequency.setValueAtTime(f,t);
    if(f2)o.frequency.exponentialRampToValueAtTime(f2,t+d);
    g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(v,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+d);
    o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.05);
  }
  const play=fn=>()=>{if(on&&init())fn();};
  return{
    get on(){return on},
    set(v){on=v;try{localStorage.setItem("np_sound",v?"on":"off");}catch{}},
    click:play(()=>{tone(420,0,.13,"sine",.12,840);tone(1260,.02,.08,"triangle",.025);}),
    nav:play(()=>{tone(600,0,.11,"sine",.08,900);tone(900,.05,.13,"sine",.04);}),
    pick:play(()=>tone(500,0,.09,"sine",.07,720)),
    success:play(()=>[523.25,659.25,783.99,1046.5].forEach((f,i)=>tone(f,i*.09,.4,"sine",.09))),
    error:play(()=>tone(230,0,.2,"triangle",.1,150))
  };
})();
(function(){
  /* click sound on every button */
  document.addEventListener("click",e=>{
    const b=e.target.closest?.("button,.btn,[data-act],[data-gen],[data-read],[data-q]");
    if(b&&!b.classList.contains("nav-btn")&&!b.classList.contains("pill"))Snd.click();
