    document.querySelectorAll(".col.over").forEach(x=>{if(x!==c)x.classList.remove("over");});
    c.classList.add("over");
  });
  document.addEventListener("drop",e=>{
    const c=e.target.closest?.(".board .col");if(!c||!dragId)return;
    e.preventDefault();const to=c.dataset.col,id=dragId;dragId=null;c.classList.remove("over");move(id,to);
  });
  function move(id,to){
    const p=find(id);if(!p)return;
    const btn=a=>document.querySelector(`.board [data-act="${a}"][data-id="${id}"]`),st=p.status;
    if(to==="Approved"){
      if(st==="draft"||st==="rejected")btn("approve")?.click();
      else if(st==="scheduled")btn("unsched")?.click();
    }else if(to==="Scheduled"){
      if(st==="approved"||st==="scheduled")btn("sched")?.click();
      else toast("Approve the post first, then schedule it.","error");
    }else if(to==="Published"){
      if(st==="approved")btn("now")?.click();
      else toast(st==="published"?"Already published.":"Approve the post first.","error");
    }else if(to==="Draft"&&st!=="draft"&&st!=="rejected"){
      toast("Posts can't move back to Draft.","error");
    }
  }
})();
