const input = $input.first().json;
const body = input.body || input;

// Get caption and image
const caption =
  body.caption ||
  body.ai_caption ||
  body.text ||
  "";

const image =
  body.image ||
  body.photo ||
  body.imageData ||
  "";

// Validate caption
if (!caption.trim()) {
  throw new Error("Caption not received from NeuralPost");
}

// =====================================
// 1. NEWSFEED POST (TEXT ONLY)
// =====================================

if (!image) {
  return [
    {
      json: {
        type: "news",
        caption: caption,
        postType: "news"
      }
    }
  ];
}

// =====================================
// 2. PHOTO POST (IMAGE + CAPTION)
// =====================================

// Check image format
const match = image.match(
  /^data:(image\/[^;]+);base64,([\s\S]+)$/
);

if (!match) {
  throw new Error(
    "Invalid image format. Expected base64 image data."
  );
}

// Return image as binary
return [
  {
    json: {
      type: "photo",
      caption: caption,
      postType: "photo"
    },
    binary: {
      data: {
        data: match[2],
        mimeType: match[1],
        fileName: "linkedin-image." + match[1].split("/")[1]
      }
    }
  }
];

const out = [];

for (const item of $input.all()) {
  const a = item.json;
  let image = a.image || a.enclosure?.url || '';

  if (!image && a.link) {
    try {
      const html = await this.helpers.httpRequest({
        method: 'GET',
        url: a.link,
        headers: { 'User-Agent': 'Mozilla/5.0' },
        timeout: 8000
      });
      const s = typeof html === 'string' ? html : JSON.stringify(html);
      const m =
        s.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
        s.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
      if (m) image = m[1].replace(/&amp;/g, '&');
    } catch (e) {}
  }

  out.push({ json: { ...a, image } });
}

return out;
